// Writes plugin.yaml from the tool list in run.mjs (node run.mjs --manifest), so the manifest
// never drifts from the code. Run after `npm run build`.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';

const tools = JSON.parse(execFileSync(process.execPath, ['run.mjs', '--manifest'], { encoding: 'utf8' }));
const pkg = JSON.parse(readFileSync('package.json', 'utf8'));
const q = (s) => JSON.stringify(String(s));
const lines = [
  '# GSX tools for GeoSpaX 3. Generated by gen-manifest.mjs from src/tools.ts (do not edit by hand).',
  '# The analysis comes from GeoSpaX 2.0 (jm0535/GeoSpaX) and 1.4.2 (jm0535/map-kit).',
  'plugin: gsx',
  `version: ${pkg.version}`,
  'title: GSX conservation and environment tools',
  `description: ${q(`${tools.length} conservation, biodiversity and environmental analysis tools from GeoSpaX 2.0: suitability, protection gaps, minimum-cost representation, fragmentation, connectivity, change, clusters and diversity. Runs on Node, offline.`)}`,
  'author: J. Moses (GeoSpaX 1.4.2 and 2.0) · plugin by GeoSpaX',
  'license: MIT',
  'homepage: https://github.com/jmozez/geospax',
  'kind: process',
  'geojson: true',
  'run: node --no-warnings ${plugin}/run.mjs ${tool}',
  'tools:',
];
for (const t of tools) {
  lines.push(`  - id: ${q(t.id)}`, `    name: ${q(t.name)}`, `    summary: ${q(t.summary)}`, `    group: ${q(t.group)}`, `    icon: ${t.icon}`, '    params:');
  for (const p of t.params) {
    const f = [`name: ${q(p.name)}`, `label: ${q(p.label)}`, `kind: ${p.kind}`];
    if (p.required) f.push('required: true');
    if (p.default !== undefined) f.push(`default: ${JSON.stringify(p.default)}`);
    if (p.description) f.push(`description: ${q(p.description)}`);
    if (p.choices) f.push(`choices: [${p.choices.map(q).join(', ')}]`);
    lines.push(`      - { ${f.join(', ')} }`);
  }
}
writeFileSync('plugin.yaml', lines.join('\n') + '\n');
console.log(`plugin.yaml: ${tools.length} tools`);
